"""OSWorld UI Element implementation."""
import xml.etree.ElementTree as ET
from typing import Any, List, Tuple, Optional

class UIElement:
    """UI Element for OSWorld platform."""

    def __init__(self, root: ET.Element):
        self.root = root
        self._children_cache = None

    @staticmethod
    def nodeFromTree(xml_string: str) -> 'UIElement':
        """Create UIElement from XML string."""
        root = ET.fromstring(xml_string)
        return UIElement(root)

    def children(self) -> List['UIElement']:
        """Get children of this element."""
        if self._children_cache is None:
            self._children_cache = [UIElement(child) for child in self.root]
        return self._children_cache

    def position(self) -> Tuple[int, int]:
        """Get element position."""
        attr = self.root.get('{http://www.w3.org/1999/xlink}screencoord', '')
        if attr:
            coords = attr.strip('()').split(',')
            return (int(coords[0]), int(coords[1]))
        return (0, 0)

    def size(self) -> Tuple[int, int]:
        """Get element size."""
        attr = self.root.get('{http://www.w3.org/1999/xlink}size', '')
        if attr:
            dims = attr.strip('()').split(',')
            return (int(dims[0]), int(dims[1]))
        return (0, 0)

    def role(self) -> str:
        """Get element role."""
        return self.root.tag
