"""MacOS UI Element implementation using pyobjc."""
from typing import Any, Dict, List, Tuple

class UIElement:
    """UI Element for MacOS platform using accessibility API."""

    def __init__(self, ax_element: Any):
        self.ax_element = ax_element

    def attribute(self, name: str) -> Any:
        """Get attribute by name."""
        return self.ax_element.attribute_forName_(name)

    def position(self) -> Tuple[float, float]:
        """Get element position from AXElement."""
        pos_attr = self.attribute('AXPosition')
        if pos_attr:
            repr_str = repr(pos_attr)
            if 'x:' in repr_str and 'y:' in repr_str:
                parts = repr_str.replace('x:', '').replace('y:', '').split()
                if len(parts) >= 2:
                    return (float(parts[0]), float(parts[1]))
        return (0.0, 0.0)

    def size(self) -> Tuple[float, float]:
        """Get element size from AXElement."""
        size_attr = self.attribute('AXSize')
        if size_attr:
            repr_str = repr(size_attr)
            if 'w:' in repr_str and 'h:' in repr_str:
                parts = repr_str.replace('w:', '').replace('h:', '').split()
                if len(parts) >= 2:
                    return (float(parts[0]), float(parts[1]))
        return (0.0, 0.0)

    @staticmethod
    def get_current_applications(obs: Dict = None) -> List[str]:
        """Get list of current running applications."""
        try:
            from AppKit import NSWorkspace
            workspace = NSWorkspace.sharedWorkspace()
            apps = workspace.runningApplications()
            return [app.localizedName() for app in apps if app.activationPolicy() == 0]
        except Exception:
            return []
EOF

